#!/usr/bin/env node
// Writes src/shopify/filters/registry.generated.ts from Shopify's theme-liquid-docs (data/filters.json).
// Usage: node bin/shopify-filter-registry.js <path to a theme-liquid-docs checkout>
// Check out the revision recorded in the generated file's header (or a newer one, on purpose) before running it.

const fs = require('fs')
const path = require('path')
const { execFileSync } = require('child_process')

const docsDir = process.argv[2]
if (!docsDir) {
  console.error('usage: node bin/shopify-filter-registry.js <theme-liquid-docs checkout>')
  process.exit(1)
}
const revision = execFileSync('git', ['-C', docsDir, 'rev-parse', 'HEAD'], { encoding: 'utf8' }).trim()
const docs = JSON.parse(fs.readFileSync(path.join(docsDir, 'data', 'filters.json'), 'utf8'))

const quote = (text) => `'${String(text).replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\n/g, ' ')}'`
const ALIAS = /has an alias of `([a-z_]+)`/g

const byName = new Map()
for (const doc of docs) {
  if (byName.has(doc.name)) continue
  const text = `${doc.description || ''} ${doc.summary || ''}`
  const aliases = []
  let match
  while ((match = ALIAS.exec(text))) {
    if (!aliases.includes(match[1])) aliases.push(match[1])
  }
  byName.set(doc.name, { name: doc.name, aliases, category: doc.category || '', deprecated: !!doc.deprecated, syntax: doc.syntax || '' })
}

const lines = [...byName.values()]
  .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
  .map(entry => `  { name: ${quote(entry.name)}, aliases: [${entry.aliases.map(quote).join(', ')}], category: ${quote(entry.category)}, deprecated: ${entry.deprecated}, syntax: ${quote(entry.syntax)} }`)

const out = `// Generated by bin/shopify-filter-registry.js from Shopify/theme-liquid-docs ${revision} (data/filters.json). Do not edit; re-run the script.
import type { ShopifyFilterDoc } from './types'

export const THEME_LIQUID_DOCS_REVISION = ${quote(revision)}

export const SHOPIFY_FILTER_DOCS: ShopifyFilterDoc[] = [
${lines.join(',\n')}
]
`
const target = path.resolve(__dirname, '..', 'src', 'shopify', 'filters', 'registry.generated.ts')
fs.writeFileSync(target, out)
console.log(`wrote ${byName.size} filters from theme-liquid-docs ${revision} to ${path.relative(process.cwd(), target)}`)
